class Solution {
public:
    string reorderSpaces(string text) {
        int spaces = count(text.begin(), text.end(), ' ');
        stringstream ss(text);
        vector<string> words;
        string w;
        while (ss >> w) words.push_back(w);
        int n = words.size();
        if (n == 1) return words[0] + string(spaces, ' ');
        int gap = spaces / (n - 1), extra = spaces % (n - 1);
        string res;
        for (int i = 0; i < n; ++i) {
            res += words[i];
            if (i + 1 < n) res += string(gap, ' ');
        }
        return res + string(extra, ' ');
    }
};

