class Solution {
    public String reorderSpaces(String text) {
        int spaces = 0;
        for (char c : text.toCharArray()) if (c == ' ') spaces++;
        String[] words = text.trim().split("\\s+");
        int n = words.length;
        int gap = n > 1 ? spaces / (n - 1) : 0;
        int extra = n > 1 ? spaces % (n - 1) : spaces;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(words[i]);
            if (i < n - 1) {
                for (int j = 0; j < gap; j++) sb.append(' ');
            }
        }
        for (int j = 0; j < extra; j++) sb.append(' ');
        return sb.toString();
    }
}

