    let spaces = 0;
    const words = [];
    let cur = '';
    for (const c of text) {
        if (c === ' ') {
            spaces++;
            if (cur) { words.push(cur); cur = ''; }
        } else {
            cur += c;
        }
    }
    if (cur) words.push(cur);
